<script setup lang="ts">
import { ref, watch } from 'vue'
import { api } from '../api'
import type { Attempt } from '../types'
const props=defineProps<{attempt:Attempt}>(), emit=defineEmits<{'saved':[value:Attempt]}>()
const read=ref<(number|null)[]>([]),tech=ref<(number|null)[]>([]),rationale=ref(''),status=ref('not_assessed'),time=ref(''),aux=ref(''),total=ref(''),reason=ref(''),error=ref(''),saving=ref(false)
watch(()=>props.attempt, a=>{read.value=a.review?.readability.slice()||[null,null,null,null];tech.value=a.review?.technical.slice()||[null,null,null,null];rationale.value=a.review?.rationale||'';status.value=a.review?.complexity?.status||'not_assessed';time.value=a.review?.complexity?.worst_case_time||'';aux.value=a.review?.complexity?.auxiliary_space||'';total.value=a.review?.complexity?.total_space||'';reason.value=a.review?.complexity?.reasoning||'';error.value=''}, {immediate:true})
async function save(){if(read.value.includes(null)||tech.value.includes(null)){error.value='Rate all eight dimensions before saving.';return}saving.value=true;error.value='';try{const assessed=status.value==='assessed';const complexity=status.value==='not_assessed'?undefined:{status:status.value,worst_case_time:assessed?time.value:null,auxiliary_space:assessed?aux.value:null,total_space:assessed?total.value:null,reasoning:reason.value};const result=await api<Attempt>(`/attempts/${props.attempt.id}/review`,{method:'PUT',body:JSON.stringify({readability:read.value,technical:tech.value,rationale:rationale.value, ...(complexity?{complexity}:{})})});emit('saved',result)}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
</script>
<template><form class="review-form" @submit.prevent="save"><h3>Organizer code review</h3><p class="muted">Rate each dimension 0–4: missing, weak, partial, good, strong. Review the saved source; grading weights stay unchanged.</p><p v-if="error" class="error-box" role="alert">{{ error }}</p>
  <fieldset><legend>Readability</legend><label v-for="(d,i) in attempt.rubric.readability" :key="d">{{ d }}<select v-model="read[i]" :aria-label="`Readability: ${d}`" required><option :value="null" disabled>Select rating</option><option v-for="n in [0,1,2,3,4]" :key="n" :value="n">{{ n }}</option></select></label></fieldset>
  <fieldset><legend>Technical quality</legend><label v-for="(d,i) in attempt.rubric.technical" :key="d">{{ d }}<select v-model="tech[i]" :aria-label="`Technical quality: ${d}`" required><option :value="null" disabled>Select rating</option><option v-for="n in [0,1,2,3,4]" :key="n" :value="n">{{ n }}</option></select></label></fieldset>
  <fieldset class="complexity-form"><legend>Complexity analysis</legend><label for="organizer-analysis-status">Analysis status</label><select id="organizer-analysis-status" v-model="status"><option value="not_assessed" :disabled="!!attempt.review?.complexity">Not assessed</option><option value="assessed">Assessed</option><option value="unable_to_assess">Unable to assess</option></select><template v-if="status==='assessed'"><label for="organizer-time">Worst-case time</label><input id="organizer-time" v-model="time" required maxlength="240"><label for="organizer-aux">Auxiliary space</label><input id="organizer-aux" v-model="aux" required maxlength="240"><label for="organizer-total">Space including stored input/output</label><input id="organizer-total" v-model="total" required maxlength="240"></template><template v-if="status!=='not_assessed'"><label for="organizer-reason">Complexity reasoning</label><textarea id="organizer-reason" v-model="reason" required maxlength="4000"></textarea></template></fieldset>
  <label for="organizer-rationale">Review rationale</label><textarea id="organizer-rationale" v-model="rationale" required maxlength="4000"></textarea><button class="primary" :disabled="saving">{{ saving?'Saving…':'Save organizer review' }}</button>
</form></template>
